function getStarterPrimaryElement(baseId) {
  const s3 = POKE_DB[STARTER_LEARNSETS[baseId]?.chain[2] || baseId];
  if (!s3 || !s3.t) return "normal";
  if (s3.t.includes("grass")) return "grass";
  if (s3.t.includes("fire")) return "fire";
  if (s3.t.includes("water")) return "water";
  return s3.t[0];
}

// Compute active Elemental Set Synergies based on equipped moves & companions!
function getActiveSynergyCounts() {
  const counts = { syn_fire: 0, syn_water: 0, syn_grass: 0, syn_storm: 0, syn_earth: 0, syn_astral: 0 };
  if (!RUN || !RUN.moves) return counts;
  const allTypes = [];
  for (const ms of RUN.moves) {
    const m = MOVES_DB[ms.id];
    if (m) allTypes.push(m.t);
    if (ms.unionPartnerId && MOVES_DB[ms.unionPartnerId]) allTypes.push(MOVES_DB[ms.unionPartnerId].t);
  }
  for (const comp of (RUN.companions || [])) {
    const m = MOVES_DB[comp.moveId];
    if (m) allTypes.push(m.t);
  }
  for (const t of allTypes) {
    for (const syn of ELEMENT_SYNERGY_SETS) {
      if (syn.types.includes(t)) counts[syn.id]++;
    }
  }
  return counts;
}

function hasGeneticRelic(relicId) {
  return !!(RUN && RUN.relics && RUN.relics.includes(relicId));
}

function getPassiveLv(itemId) {
  return (RUN && RUN.heldItems && RUN.heldItems[itemId]) || 0;
}

function getEquippedPassiveIds() {
  if (!RUN || !RUN.heldItems) return [];
  return Object.keys(RUN.heldItems).filter(k => PASSIVE_HELD_MAP[k] && RUN.heldItems[k] > 0);
}

// Check if a move slot is eligible for ★Catalyst Evolution (2+ sockets OR Lv.12+ AND matching catalyst passive owned!)
function canMoveCatalystEvolve(mSlot) {
  if (!RUN || !mSlot) return false;
  if (mSlot.evolvedSuper || mSlot.mods.length >= 3) return true;
  if (mSlot.mods.length < 2) return false;
  const m = MOVES_DB[mSlot.id];
  if (!m) return false;
  const rec = WEAPON_EVO_RECIPES[m.pat];
  if (!rec) return false;
  if (getPassiveLv("magnet_core") >= 5) return true;
  return rec.cats.some(cid => getPassiveLv(cid) >= 1);
}

function isMoveSuperWeapon(mSlot) {
  return !!(mSlot && (mSlot.evolvedSuper || mSlot.unionData || (mSlot.mods && mSlot.mods.length >= 3)));
}

function getMaxMoveSlots() {
  if (!RUN) return 4;
  return 4 + Math.min(2, RUN.unionBonusSlots || 0);
}

function getTargetEnemyLevel(isBoss = false, isElite = false) {
  if (!RUN) return 4;
  const df = getActiveDiff();
  const pLv = RUN.level || 5;
  const timeMin = RUN.time / 60;
  const tScale = df.timeScaleMul;
  const timeLv = (timeMin * 2.4 + Math.pow(Math.max(0, timeMin - 3.0), 1.38) * 1.7) * tScale;
  const baseLv = Math.round(Math.max(pLv * (0.80 + tScale * 0.10), 4 + timeLv) + RUN.stage.lvOffset + df.lvOffset);
  const offset = isBoss ? (df.id === "n1" ? 2 : (df.id === "n2" ? 4 : 5)) : (isElite ? 1 : 0);
  return Math.max(3, baseLv + offset);
}

function computePokemonStats(speciesId, level, isPlayer = false, isBoss = false, runBuffs = null) {
  const entry = POKE_DB[speciesId] || { t: ["normal"], s: [60, 60, 60, 60, 60, 60], bst: 360 };
  const [bHp, bAtk, bDef, bSpa, bSpd, bSpe] = entry.s;

  const coreHp = Math.floor(((2 * bHp + 31) * level) / 100) + level + 10;
  const pLv = RUN ? RUN.level : 5;
  const pEvo = RUN ? RUN.evoStage : 0;
  const timeMin = RUN ? (RUN.time / 60) : 0;

  const df = getActiveDiff();
  // Smooth, non-spongey wave fortitude curve so builds feel powerful and crispy all run long!
  const vsWaveFortitude = 1 + (Math.max(0, timeMin - 1.8) * 0.26 + Math.pow(Math.max(0, timeMin - 3.8), 1.45) * 0.36) * df.timeScaleMul;
  const evoScale = (1 + pEvo * 0.22 + Math.max(0, pLv - 8) * 0.026) * vsWaveFortitude * df.hpMul;

  let maxHp = coreHp;
  if (isPlayer) {
    const evPct = getEvBonusPct("hp") * 0.01;
    const vitStacks = (RUN && RUN.hexes && RUN.hexes.sv_vitality) || 0;
    const shellBonus = getPassiveLv("shell_bell") * 0.08;
    const goliathBonus = RUN ? (RUN.goliathHpBonus || 0) : 0;
    const goliathMul = (RUN && RUN.hexes && RUN.hexes.goliath) ? 1.22 : 1.0;
    const turtwigBonus = (RUN && RUN.baseId === 387) ? 1.22 : 1.0;
    const glassMul = hasGeneticRelic("relic_glass_cannon") ? 0.75 : 1.0;
    maxHp = Math.floor(((coreHp * 2.65 + 64) * (1 + evPct + vitStacks * 0.15 + shellBonus) * goliathMul * turtwigBonus * glassMul) + goliathBonus);
  } else if (isBoss) {
    maxHp = Math.floor((coreHp * 14.5 + 260) * evoScale);
  } else {
    maxHp = Math.floor((coreHp * 1.32 + 12) * evoScale);
  }

  const syns = isPlayer ? getActiveSynergyCounts() : null;

  const statFn = (base, key) => {
    const raw = Math.floor(((2 * base + 31) * level) / 100) + 8;
    if (!isPlayer) {
      const enemyTimeMul = (1 + pEvo * 0.12 + (Math.max(0, timeMin - 2.5) * 0.14 + Math.pow(Math.max(0, timeMin - 4.5), 1.22) * 0.11) * df.timeScaleMul) * df.atkMul;
      return Math.max(6, Math.floor(raw * enemyTimeMul));
    }
    let bonusPct = getEvBonusPct(key) * 0.01 + ((runBuffs && runBuffs[key]) || 0) * 0.05;
    if (RUN && RUN.hexes) {
      if ((key === "atk" || key === "spa") && RUN.hexes.sv_might) bonusPct += Math.min(5, RUN.hexes.sv_might) * 0.10;
      if ((key === "def" || key === "spd") && RUN.hexes.sv_armor) bonusPct += Math.min(5, RUN.hexes.sv_armor) * 0.12;
      if (RUN.hexes.sv_dice_bag && (key === "def" || key === "spd")) bonusPct += RUN.hexes.sv_dice_bag * 0.06;
    }
    // Passive Held Item Stat Scaling
    if (key === "atk" || key === "spa") {
      bonusPct += getPassiveLv("muscle_band") * 0.09 + getPassiveLv("wise_glasses") * 0.09;
    }
    if (key === "def" || key === "spd") {
      bonusPct += getPassiveLv("rocky_helmet") * 0.12;
    }
    // Genetic Relic Stat Rules
    if (hasGeneticRelic("relic_glass_cannon") && (key === "atk" || key === "spa")) bonusPct += 0.55;
    if (hasGeneticRelic("relic_turret_fortress") && (key === "def" || key === "spd")) bonusPct += 0.35;
    // Elemental Synergy Set Stat Bonuses
    if (syns) {
      if (syns.syn_earth >= 2 && (key === "atk" || key === "def" || key === "spd")) bonusPct += 0.20;
      if (syns.syn_astral >= 2 && key === "spa") bonusPct += 0.20;
    }
    // Starter Innate Stat Passives
    if (RUN) {
      if (RUN.baseId === 7 && (key === "def" || key === "spd")) bonusPct += 0.20;
      if (RUN.baseId === 252 && key === "spe") bonusPct += 0.18;
      if (RUN.baseId === 155 && key === "spa" && RUN.hp >= RUN.maxHp * 0.6) bonusPct += 0.22;
      if (RUN.baseId === 909 && key === "spa") bonusPct += Math.min(0.42, (RUN.fuecocoStacks || 0) * 0.006);
    }
    return Math.floor(raw * (1 + bonusPct));
  };

  let add = [0, 0, 0, 0, 0, 0];
  if (isPlayer && RUN && RUN.ultActive && RUN.awakening && RUN.awakening.statAdd) {
    add = RUN.awakening.statAdd;
  }
  return {
    types: entry.t,
    bst: entry.bst + (isPlayer && RUN && RUN.ultActive && RUN.awakening ? 100 : 0),
    maxHp: maxHp + Math.floor(add[0] * 3.2),
    atk: statFn(bAtk + add[1], "atk"),
    def: statFn(bDef + add[2], "def"),
    spa: statFn(bSpa + add[3], "spa"),
    spd: statFn(bSpd + add[4], "spd"),
    spe: statFn(bSpe + add[5], "spe")
  };
}

function getMoveSlotById(moveId) {
  if (!RUN || !RUN.moves) return null;
  for (let i = 0; i < RUN.moves.length; i++) {
    if (RUN.moves[i].id === moveId) return RUN.moves[i];
  }
  return null;
}

function hasMoveMod(mSlot, modId) {
  if (!mSlot || !mSlot.mods) return 0;
  let cnt = 0;
  for (let i = 0; i < mSlot.mods.length; i++) {
    if (mSlot.mods[i] === modId) cnt++;
  }
  return cnt;
}

function computeMoveCooldown(moveId, attackerStats, heldItems = null, mSlot = null) {
  const m = MOVES_DB[moveId];
  if (!m) return 1.10;
  const effPower = m.p * (m.h > 1 ? (m.h > 2 ? 2.1 : 1.55) : 1.0);
  let baseCd = 0.68 + Math.pow(effPower / 44, 0.65) * 0.42;
  if (m.pat === "bible_orbit") baseCd = 2.3;
  else if (m.pat === "santa_hazard" || m.pat === "gravity_well") baseCd = 1.95;
  else if (m.pat === "sonic_boom") baseCd = 0.96;
  else if (m.pat === "fist_flurry" || m.pat === "spear_thrust") baseCd *= 0.84;

  const speFactor = Math.max(0.64, Math.min(1.10, 110 / (85 + attackerStats.spe * 0.44)));
  const scarfBonus = Math.pow(0.93, getPassiveLv("choice_scarf"));

  let hexCdMul = 1.0;
  if (mSlot) {
    const scd = hasMoveMod(mSlot, "s_cd");
    if (scd > 0) hexCdMul *= Math.pow(0.88, scd);
    const gat = hasMoveMod(mSlot, "gatling");
    if (gat > 0) hexCdMul *= Math.pow(0.68, gat);
    if (isMoveSuperWeapon(mSlot)) hexCdMul *= 0.84;
    if (mSlot.unionData) hexCdMul *= 0.85;
  }
  if (RUN && attackerStats === RUN.stats) {
    if (RUN.hexes) {
      if (RUN.hexes.sv_haste) hexCdMul *= Math.pow(0.92, Math.min(4, RUN.hexes.sv_haste));
      if (RUN.hexes.berserker_drive) hexCdMul *= Math.pow(0.88, RUN.hexes.berserker_drive);
      if (RUN.hexes.gd_swift_exec && mSlot && mSlot !== RUN.moves[0]) hexCdMul *= 0.80;
    }
    if (hasGeneticRelic("relic_glass_cannon")) hexCdMul *= 0.82;
    if (hasGeneticRelic("relic_turret_fortress") && Math.hypot(RUN.vx || 0, RUN.vy || 0) < 0.08) hexCdMul *= 0.75;
    const syns = getActiveSynergyCounts();
    if (syns.syn_water >= 4) hexCdMul *= 0.82;

    if (RUN.baseId === 252 && (m.pat === "iaijutsu_slash" || m.t === "grass")) hexCdMul *= 0.84;
    if (RUN.baseId === 255) hexCdMul *= (1 - Math.min(0.20, (RUN.torchicCombo || 0) * 0.01));
    if (RUN.baseId === 912 && (RUN.quaxlyDanceT || 0) > 0) hexCdMul *= 0.80;
    if (RUN.ultActive) hexCdMul *= 0.72;
  }
  return Math.max(0.32, baseCd * speFactor * scarfBonus * hexCdMul);
}

function calculatePokemonDamage(attackerLv, attackerStats, moveId, defenderLv, defenderStats, aoeScale = 1.0, heldItems = null, mSlot = null, targetEnemy = null) {
  const m = MOVES_DB[moveId];
  if (!m) return { dmg: 6, eff: 1.0, isCrit: false, stab: 1.0 };

  const isPhys = m.c === "physical";
  // Adaptive Hybrid Scaling: uses 100% of matching stat OR 82% of your higher offensive stat so cross-category moves always hit hard!
  const rawA = isPhys ? attackerStats.atk : attackerStats.spa;
  const bestA = Math.max(attackerStats.atk, attackerStats.spa);
  const A = Math.max(rawA, Math.floor(bestA * 0.82));
  const D = Math.max(1, isPhys ? defenderStats.def : defenderStats.spd);

  const isPlayerAtk = (RUN && attackerStats === RUN.stats);
  const isTera = isPlayerAtk && RUN.ultActive && RUN.awakening && RUN.awakening.kind === "tera";
  const hasProtean = isPlayerAtk && (RUN.baseId === 656 || RUN.baseId === 813 || hasGeneticRelic("relic_elemental_conductor"));
  const stab = (hasProtean || attackerStats.types.includes(m.t)) ? (isTera ? 2.1 : (hasGeneticRelic("relic_elemental_conductor") ? 1.6 : 1.5)) : 1.0;
  const awkMul = (isPlayerAtk && RUN.ultActive) ? 1.38 : 1.0;

  let eff = getTypeEffectiveness(m.t, defenderStats.types);

  let extraCrit = getPassiveLv("scope_lens") * 8;
  let critDmgMul = 1.55 + getPassiveLv("scope_lens") * 0.14;

  if (mSlot) {
    extraCrit += hasMoveMod(mSlot, "s_crit") * 12;
    critDmgMul += hasMoveMod(mSlot, "s_crit") * 0.20;
    if (isMoveSuperWeapon(mSlot)) extraCrit += 8;
  }
  if (isPlayerAtk && RUN.hexes) {
    if (RUN.hexes.sv_crit_rate) extraCrit += RUN.hexes.sv_crit_rate * 8;
    if (RUN.hexes.sv_crit_dmg) critDmgMul += RUN.hexes.sv_crit_dmg * 0.22;
    if (RUN.hexes.jeweled_gauntlet) {
      extraCrit += 25;
      critDmgMul += 0.45;
    }
  }
  if (isPlayerAtk) {
    if (hasGeneticRelic("relic_crit_nova")) extraCrit += 18;
    if (hasGeneticRelic("relic_gambler_dice")) extraCrit += Math.min(20, RUN.gamblerStacks || 0) * 3;
    if (RUN.baseId === 4 && (m.t === "fire" || m.t === "dragon")) {
      extraCrit += 12;
      if (targetEnemy && targetEnemy.burnT > 0) critDmgMul += 0.30;
    }
    if (RUN.baseId === 255) extraCrit += 14;
    if (RUN.baseId === 501) critDmgMul += 0.30;
    if (RUN.baseId === 816) { extraCrit += 16; critDmgMul += 0.45; }
    if (RUN.baseId === 906) extraCrit += 16;
  } else if (hasGeneticRelic("relic_swarm_commander")) {
    extraCrit += 20;
  }

  const isCrit = Math.random() * 100 < ((m.cr || 8) + extraCrit);
  const critMul = isCrit ? critDmgMul : 1.0;

  let modDmgMul = 1.0;
  if (mSlot) {
    modDmgMul *= (1 + mSlot.mods.length * 0.10);
    if (hasMoveMod(mSlot, "s_power") > 0) modDmgMul *= (1 + 0.18 * hasMoveMod(mSlot, "s_power"));
    if (hasMoveMod(mSlot, "colossal") > 0) modDmgMul *= (1 + 0.25 * hasMoveMod(mSlot, "colossal"));
    if (hasMoveMod(mSlot, "reaper") > 0) modDmgMul *= 1.35;
    if (targetEnemy && hasMoveMod(mSlot, "s_exec") > 0 && targetEnemy.hp <= targetEnemy.maxHp * 0.45) {
      modDmgMul *= (1 + 0.28 * hasMoveMod(mSlot, "s_exec"));
    }
    if (targetEnemy && (targetEnemy.isElite || targetEnemy.isBoss) && hasMoveMod(mSlot, "s_boss") > 0) {
      modDmgMul *= (1 + 0.25 * hasMoveMod(mSlot, "s_boss"));
    }
    if (isMoveSuperWeapon(mSlot)) modDmgMul *= 1.38; // ★Super-Weapon Evolution Power Spike!
    if (mSlot.unionData) modDmgMul *= 1.45; // ★★Mythic Union Super-Weapon Multiplier!
  }

  if (isPlayerAtk && RUN) {
    // Passive Held Item Multipliers
    if (getPassiveLv("life_orb") > 0) {
      modDmgMul *= (1 + 0.15 * getPassiveLv("life_orb"));
      if (targetEnemy && (targetEnemy.isElite || targetEnemy.isBoss)) modDmgMul *= (1 + 0.10 * getPassiveLv("life_orb"));
    }
    if (getPassiveLv("charcoal") > 0 && ["fire", "dragon", "electric"].includes(m.t)) {
      modDmgMul *= (1 + 0.14 * getPassiveLv("charcoal"));
    }
    if (getPassiveLv("mystic_water") > 0 && ["water", "ice", "psychic"].includes(m.t)) {
      modDmgMul *= (1 + 0.14 * getPassiveLv("mystic_water"));
    }
    if (getPassiveLv("miracle_seed") > 0 && ["grass", "poison", "bug"].includes(m.t)) {
      modDmgMul *= (1 + 0.14 * getPassiveLv("miracle_seed"));
    }
    if (getPassiveLv("muscle_band") > 0 && ["whip_wave", "iaijutsu_slash", "fist_flurry", "crunch_fangs", "spear_thrust"].includes(m.pat)) {
      modDmgMul *= (1 + 0.08 * getPassiveLv("muscle_band"));
    }

    // Genetic Relic Multipliers
    if (hasGeneticRelic("relic_blood_mage")) {
      modDmgMul *= (1 + Math.floor(RUN.maxHp / 10) * 0.025);
    }
    if (hasGeneticRelic("relic_lone_wolf") && RUN.companions.length === 0) {
      modDmgMul *= 1.45;
    }
    if (hasGeneticRelic("relic_elemental_conductor")) {
      const uniqueTypes = new Set(RUN.moves.map(ms => MOVES_DB[ms.id]?.t).filter(Boolean)).size;
      modDmgMul *= (1 + uniqueTypes * 0.14);
    }
    if (hasGeneticRelic("relic_gambler_dice") && (RUN.gamblerStacks || 0) > 0) {
      modDmgMul *= (1 + Math.min(20, RUN.gamblerStacks) * 0.04);
    }
    if (hasGeneticRelic("relic_speed_demon")) {
      const spdBonusPct = Math.max(0, ((RUN.curSpdMul || 1.0) - 1.0) * 100);
      modDmgMul *= (1 + spdBonusPct * 0.015);
    }

    // Elemental Synergy Set Multipliers
    const syns = getActiveSynergyCounts();
    if (syns.syn_fire >= 2 && ["fire", "dragon"].includes(m.t)) modDmgMul *= 1.18;
    if (syns.syn_water >= 2 && ["water", "ice"].includes(m.t)) modDmgMul *= 1.18;
    if (syns.syn_water >= 4 && targetEnemy && targetEnemy.slowT > 0) modDmgMul *= 1.35;
    if (syns.syn_grass >= 2 && ["grass", "poison", "bug"].includes(m.t)) modDmgMul *= 1.18;

    if (RUN.hexes) {
      if (RUN.hexes.berserker_drive) {
        const missingPct = Math.max(0, (1 - RUN.hp / Math.max(1, RUN.maxHp)) * 10);
        modDmgMul *= (1 + missingPct * 0.07 * RUN.hexes.berserker_drive);
      }
      if (RUN.hexes.gd_heavy_ord) modDmgMul *= (1 + 0.28 * RUN.hexes.gd_heavy_ord);
      if (RUN.hexes.sv_boss_hunt && targetEnemy && (targetEnemy.isElite || targetEnemy.isBoss)) {
        modDmgMul *= (1 + 0.18 * RUN.hexes.sv_boss_hunt);
      }
      if (RUN.hexes.sv_water_tide && targetEnemy && (targetEnemy.slowT > 0 || targetEnemy.burnT > 0 || targetEnemy.leechT > 0 || targetEnemy.rootT > 0)) {
        modDmgMul *= (1 + 0.18 * RUN.hexes.sv_water_tide);
      }
    }

    if (RUN.baseId === 158 && (m.pat === "crunch_fangs" || m.pat === "iaijutsu_slash")) modDmgMul *= 1.25;
    if (RUN.baseId === 258 && targetEnemy && targetEnemy.slowT > 0) modDmgMul *= 1.25;
    if (RUN.baseId === 498) {
      const miss = Math.max(0, (1 - RUN.hp / Math.max(1, RUN.maxHp)) * 10);
      modDmgMul *= (1 + miss * 0.07);
    }
    if (RUN.baseId === 722 && targetEnemy && Math.hypot(targetEnemy.x - RUN.x, targetEnemy.y - RUN.y) >= 120) modDmgMul *= 1.28;
    if (RUN.baseId === 725 && (m.t === "fire" || m.t === "dark")) modDmgMul *= 1.25;
    if (RUN.baseId === 810) modDmgMul *= 1.20;
  }

  if (!isPlayerAtk && RUN) {
    if (RUN.hexes && RUN.hexes.sv_comp_train) modDmgMul *= (1 + 0.14 * RUN.hexes.sv_comp_train);
    if (RUN.hexes && RUN.hexes.gd_companion) modDmgMul *= (1 + 0.30 * RUN.hexes.gd_companion);
    if (hasGeneticRelic("relic_lone_wolf")) modDmgMul *= 1.60;
  }

  const randVar = 0.94 + Math.random() * 0.12;
  const baseDmg = (((2 * attackerLv / 5 + 2) * m.p * (A / D)) / 46 + 3);
  let finalDmg = Math.max(2, Math.round(baseDmg * stab * eff * critMul * aoeScale * awkMul * modDmgMul * randVar));
  if (isPlayerAtk && RUN.baseId === 390) {
    finalDmg += Math.round(RUN.level * 2.0);
  }
  return { dmg: finalDmg, eff, isCrit, stab };
}

// ============================================================================
// Underlying Engine Optimization #1: Re-Entrant Safe Spatial Hash Grid
// Fixes the nested `queryEnemiesInRadius` shared-array corruption & freeze bug!
// ============================================================================
const GRID_CELL = 96;
const GRID_BUCKETS = new Map();
const GRID_POOL = [];

function clearSpatialGrid() {
  for (const arr of GRID_BUCKETS.values()) {
    arr.length = 0;
    GRID_POOL.push(arr);
  }
  GRID_BUCKETS.clear();
}

function insertEnemyToGrid(e) {
  const cx = Math.floor(e.x / GRID_CELL);
  const cy = Math.floor(e.y / GRID_CELL);
  const key = ((cx & 0xffff) << 16) | (cy & 0xffff);
  let bucket = GRID_BUCKETS.get(key);
  if (!bucket) {
    bucket = GRID_POOL.length > 0 ? GRID_POOL.pop() : [];
    GRID_BUCKETS.set(key, bucket);
  }
  bucket.push(e);
}

// Returns a fresh array per query so nested calls (e.g. executeUnitMove -> hitEnemyWithMove -> bounce) NEVER overwrite an outer loop's array!
function queryEnemiesInRadius(x, y, r) {
  const results = [];
  const pad = r + 38;
  const minCx = Math.floor((x - pad) / GRID_CELL);
  const maxCx = Math.floor((x + pad) / GRID_CELL);
  const minCy = Math.floor((y - pad) / GRID_CELL);
  const maxCy = Math.floor((y + pad) / GRID_CELL);

  for (let cy = minCy; cy <= maxCy; cy++) {
    const yBits = cy & 0xffff;
    for (let cx = minCx; cx <= maxCx; cx++) {
      const key = ((cx & 0xffff) << 16) | yBits;
      const bucket = GRID_BUCKETS.get(key);
      if (bucket) {
        for (let i = 0; i < bucket.length; i++) {
          const e = bucket[i];
          if (e.hp > 0) {
            const dx = e.x - x;
            const dy = e.y - y;
            const lim = r + e.radius;
            if (dx * dx + dy * dy <= lim * lim) {
              results.push(e);
            }
          }
        }
      }
    }
  }
  return results;
}

function swapRemove(arr, idx) {
  const last = arr.length - 1;
  if (idx < last) arr[idx] = arr[last];
  arr.pop();
}

let NEXT_ATTACK_UID = 1;
function allocAttackUid() {
  NEXT_ATTACK_UID = (NEXT_ATTACK_UID + 1) & 0x3fffffff;
  return NEXT_ATTACK_UID;
}

// ============================================================================
// Underlying Engine Optimization #2: Offscreen Sprite Cache + 3D Skill Model Bakery
// Pre-renders rich 2.5D/3D composite weapon & elemental models onto offscreen
// 64x64 canvases so projectiles, orbitals, shurikens, boulders, fists, and
// meteors look like sculpted 3D game models with zero per-frame shader lag!
// ============================================================================
const IMG_CACHE = new Map();
const SILHOUETTE_CACHE = new Map();
const SKILL_MODEL_CACHE = new Map();

function getImg(src) {
  let img = IMG_CACHE.get(src);
  if (img) return img;
  img = new Image();
  img.src = src;
  IMG_CACHE.set(src, img);
  return img;
}

function getWhiteSilhouette(src, img) {
  let sil = SILHOUETTE_CACHE.get(src);
  if (sil) return sil;
  if (!img.complete || img.naturalWidth === 0) return null;
  const c = document.createElement("canvas");
  c.width = img.naturalWidth;
  c.height = img.naturalHeight;
  const cctx = c.getContext("2d");
  cctx.drawImage(img, 0, 0);
  cctx.globalCompositeOperation = "source-in";
  cctx.fillStyle = "#ffffff";
  cctx.fillRect(0, 0, c.width, c.height);
  SILHOUETTE_CACHE.set(src, c);
  return c;
}

// Pre-bake 3D Composite Skill Models (64x64 offscreen canvas per modelKey)
function getSkillModelCanvas(modelKey, primaryColor = "#00e5ff") {
  const cacheKey = `${modelKey}_${primaryColor}`;
  let c = SKILL_MODEL_CACHE.get(cacheKey);
  if (c) return c;

  c = document.createElement("canvas");
  c.width = 64;
  c.height = 64;
  const g = c.getContext("2d");
  const cx = 32, cy = 32;

  if (modelKey === "leaf_blade") {
    // 3D Sculpted Emerald Razor Leaf with central glowing vein, serrated edges & wind aura
    const grad = g.createLinearGradient(8, 32, 56, 32);
    grad.addColorStop(0, "#1b5e20");
    grad.addColorStop(0.45, "#00e676");
    grad.addColorStop(0.8, "#b9f6ca");
    grad.addColorStop(1, "#ffffff");
    g.fillStyle = grad;
    g.strokeStyle = "#e8f5e9";
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(58, 32);
    g.quadraticCurveTo(36, 10, 8, 32);
    g.quadraticCurveTo(36, 54, 58, 32);
    g.closePath();
    g.fill();
    g.stroke();
    // 3D bevel highlight on upper half
    g.fillStyle = "rgba(255,255,255,0.32)";
    g.beginPath();
    g.moveTo(56, 32);
    g.quadraticCurveTo(36, 14, 12, 32);
    g.closePath();
    g.fill();
    // Central glowing vein & side ribs
    g.strokeStyle = "#ffffff";
    g.lineWidth = 2.2;
    g.beginPath();
    g.moveTo(10, 32); g.lineTo(54, 32);
    g.moveTo(26, 32); g.lineTo(34, 21);
    g.moveTo(26, 32); g.lineTo(34, 43);
    g.moveTo(38, 32); g.lineTo(45, 24);
    g.moveTo(38, 32); g.lineTo(45, 40);
    g.stroke();
  } else if (modelKey === "fire_dragon_orb") {
    // 3D Multi-Layered Magma Fireball with white-hot core, swirling flame tongues & corona
    const radG = g.createRadialGradient(cx + 4, cy, 3, cx, cy, 28);
    radG.addColorStop(0, "#ffffff");
    radG.addColorStop(0.28, "#ffff00");
    radG.addColorStop(0.62, primaryColor === "#00e5ff" ? "#00b0ff" : "#ff3d00");
    radG.addColorStop(1, "rgba(183, 28, 28, 0)");
    g.fillStyle = radG;
    g.beginPath();
    g.arc(cx, cy, 28, 0, Math.PI * 2);
    g.fill();
    // Sculpted flame crest fins
    g.fillStyle = primaryColor === "#00e5ff" ? "#00e5ff" : "#ff9100";
    g.beginPath();
    g.moveTo(56, 32);
    g.quadraticCurveTo(38, 12, 6, 18);
    g.quadraticCurveTo(22, 32, 6, 46);
    g.quadraticCurveTo(38, 52, 56, 32);
    g.fill();
    // Inner white-gold core
    g.fillStyle = "#fffde7";
    g.beginPath();
    g.arc(38, 32, 10, 0, Math.PI * 2);
    g.fill();
  } else if (modelKey === "water_shuriken") {
    // 3D Faceted Crystal Water/Golden Shuriken with metallic core & specular bevels
    const isGold = primaryColor === "#ffd600";
    for (let k = 0; k < 4; k++) {
      g.save();
      g.translate(cx, cy);
      g.rotate((k * Math.PI) / 2);
      // Left facet (bright)
      g.fillStyle = isGold ? "#fff59d" : "#80d8ff";
      g.beginPath();
      g.moveTo(0, -29);
      g.lineTo(-9, -7);
      g.lineTo(0, 0);
      g.closePath();
      g.fill();
      // Right facet (deep 3D shade)
      g.fillStyle = isGold ? "#ff8f00" : "#0277bd";
      g.beginPath();
      g.moveTo(0, -29);
      g.lineTo(9, -7);
      g.lineTo(0, 0);
      g.closePath();
      g.fill();
      g.strokeStyle = "#ffffff";
      g.lineWidth = 1.5;
      g.beginPath();
      g.moveTo(0, -29); g.lineTo(-9, -7); g.lineTo(0, 0); g.lineTo(9, -7); g.closePath();
      g.stroke();
      g.restore();
    }
    // Central jewel ring
    g.fillStyle = "#ffffff";
    g.beginPath();
    g.arc(cx, cy, 5, 0, Math.PI * 2);
    g.fill();
  } else if (modelKey === "rock_polyhedron") {
    // 3D Faceted Obsidian/Crag Boulder with magma cracks & top-left 3D lighting
    g.save();
    g.translate(cx, cy);
    // Top-left lit facet
    g.fillStyle = "#bcaaa4";
    g.beginPath();
    g.moveTo(-22, -8); g.lineTo(-6, -24); g.lineTo(14, -18); g.lineTo(0, 0); g.closePath();
    g.fill();
    // Right mid facet
    g.fillStyle = "#8d6e63";
    g.beginPath();
    g.moveTo(14, -18); g.lineTo(24, 4); g.lineTo(8, 22); g.lineTo(0, 0); g.closePath();
    g.fill();
    // Bottom-left shadow facet
    g.fillStyle = "#4e342e";
    g.beginPath();
    g.moveTo(-22, -8); g.lineTo(0, 0); g.lineTo(8, 22); g.lineTo(-14, 18); g.closePath();
    g.fill();
    // Glowing lava/energy seams
    g.strokeStyle = primaryColor;
    g.lineWidth = 2.5;
    g.beginPath();
    g.moveTo(-6, -24); g.lineTo(0, 0); g.lineTo(24, 4);
    g.moveTo(0, 0); g.lineTo(-14, 18);
    g.stroke();
    // Outer outline
    g.strokeStyle = "#d7ccc8";
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(-22, -8); g.lineTo(-6, -24); g.lineTo(14, -18); g.lineTo(24, 4); g.lineTo(8, 22); g.lineTo(-14, 18); g.closePath();
    g.stroke();
    g.restore();
  } else if (modelKey === "fist_knuckle") {
    // 3D Sculpted Martial Aura Fist with shockwave rings & knuckle plates
    g.save();
    g.translate(cx, cy);
    const fg = g.createLinearGradient(-18, 0, 22, 0);
    fg.addColorStop(0, "rgba(255, 87, 34, 0.2)");
    fg.addColorStop(0.5, primaryColor);
    fg.addColorStop(1, "#fff59d");
    g.fillStyle = fg;
    g.strokeStyle = "#ffffff";
    g.lineWidth = 2;
    // Main armored gauntlet block (pure path, no roundRect compatibility issues)
    g.fillRect(-12, -15, 25, 30);
    g.strokeRect(-12, -15, 25, 30);
    // 4 3D Knuckle ridges on front
    g.fillStyle = "#ffffff";
    for (let k = -11; k <= 11; k += 7) {
      g.beginPath();
      g.arc(14, k, 4.5, 0, Math.PI * 2);
      g.fill();
    }
    // Sonic Mach Cone in front of fist
    g.strokeStyle = "#ffeb3b";
    g.lineWidth = 2.5;
    g.beginPath();
    g.arc(10, 0, 22, -0.95, 0.95);
    g.stroke();
    g.restore();
  } else if (modelKey === "vortex_swirl") {
    // Pre-baked 3D Maelstrom / Fire Spin Vortex (Eliminates per-frame createRadialGradient in render2D!)
    const isDark = primaryColor === "#120524";
    const rg = g.createRadialGradient(cx, cy, 3, cx, cy, 30);
    rg.addColorStop(0, isDark ? "#000000" : "#ffffff");
    rg.addColorStop(0.42, isDark ? "#4a148c" : primaryColor);
    rg.addColorStop(0.82, isDark ? "#ea80fc" : "#01579b");
    rg.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = rg;
    g.beginPath();
    g.arc(cx, cy, 30, 0, Math.PI * 2);
    g.fill();
    g.save();
    g.translate(cx, cy);
    for (let arm = 0; arm < 4; arm++) {
      g.rotate(Math.PI / 2);
      g.strokeStyle = isDark ? "#00e5ff" : "#ffffff";
      g.lineWidth = 3;
      g.beginPath();
      g.arc(7, 0, 16, 0.1, Math.PI * 1.25);
      g.stroke();
    }
    g.restore();
  } else {
    // "astral_plasma_bolt": 3D Star-Core Energy Missile with dual intersecting rings & comet tail
    const rg = g.createRadialGradient(cx + 4, cy, 2, cx, cy, 24);
    rg.addColorStop(0, "#ffffff");
    rg.addColorStop(0.35, primaryColor);
    rg.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = rg;
    g.beginPath();
    g.arc(cx, cy, 24, 0, Math.PI * 2);
    g.fill();
    // 3D Tilted Orbital Rings
    g.strokeStyle = "#ffffff";
    g.lineWidth = 2;
    g.beginPath();
    g.ellipse(cx, cy, 20, 7, 0.55, 0, Math.PI * 2);
    g.stroke();
    g.strokeStyle = primaryColor;
    g.beginPath();
    g.ellipse(cx, cy, 20, 7, -0.55, 0, Math.PI * 2);
    g.stroke();
    // 4-point star diamond core
    g.fillStyle = "#ffffff";
    g.beginPath();
    g.moveTo(cx + 14, cy); g.lineTo(cx, cy - 8); g.lineTo(cx - 14, cy); g.lineTo(cx, cy + 8); g.closePath();
    g.fill();
  }

  SKILL_MODEL_CACHE.set(cacheKey, c);
  return c;
}

const MAP_CHUNK_CACHE = new Map();
function getStageChunkCanvas(st) {
  const cached = MAP_CHUNK_CACHE.get(st.id);
  if (cached) return cached;
  const gImg = getImg(st.groundTex);
  const pImg = getImg(st.pathTex);
  if (!gImg.complete || gImg.naturalWidth === 0 || !pImg.complete || pImg.naturalWidth === 0) return null;

  const chunk = document.createElement("canvas");
  chunk.width = 1024;
  chunk.height = 1024;
  const cctx = chunk.getContext("2d");
  cctx.imageSmoothingEnabled = false;
  const tileSize = 128;
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      const hash = Math.abs(((c + 3) * 73856093) ^ ((r + 5) * 19349663)) % 100;
      const tex = hash < 18 ? pImg : gImg;
      cctx.drawImage(tex, c * tileSize, r * tileSize, tileSize, tileSize);
    }
  }
  MAP_CHUNK_CACHE.set(st.id, chunk);
  return chunk;
}

function drawPokemonSprite(ctx, pid, x, y, vx, vy, animTime, scale = 1.6, flashWhite = false, ringColor = null, hopY = 0) {
  const src = `./assets/pmd/${pid}.png`;
  const img = getImg(src);
  const meta = SPRITE_META[pid] || [0, 32, 32, 4];
  const wy = meta[0], fw = meta[1], fh = meta[2], fn = meta[3];

  if (!img.complete || img.naturalWidth === 0) {
    const iconImg = getImg(`./assets/portraits/${pid}.png`);
    if (iconImg.complete && iconImg.naturalWidth > 0) {
      const sz = 36 * scale;
      ctx.drawImage(iconImg, (x - sz * 0.5) | 0, (y - sz * 0.5 - hopY) | 0, sz | 0, sz | 0);
    }
    return;
  }
  let row = 0;
  if (vx > 0.01 || vx < -0.01 || vy > 0.01 || vy < -0.01) {
    const ang = Math.atan2(vx, vy);
    row = (Math.round(ang / 0.7853981633974483) % 8 + 8) % 8;
  }
  const col = ((animTime * 8) | 0) % (fn || 1);
  const sx = col * fw;
  const sy = wy + row * fh;
  const dw = (fw * scale) | 0;
  const dh = (fh * scale) | 0;
  const dx = (x - dw * 0.5) | 0;
  const dy = (y - dh * 0.5 - hopY) | 0;

  ctx.fillStyle = "rgba(0, 0, 0, 0.34)";
  ctx.fillRect((x - dw * 0.28) | 0, (y + dh * 0.28) | 0, (dw * 0.56) | 0, (dh * 0.14) | 0);

  if (ringColor) {
    ctx.strokeStyle = ringColor;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.arc(x | 0, (y + dh * 0.30) | 0, (dw * 0.38) | 0, 0, Math.PI * 2);
    ctx.stroke();
  }

  ctx.drawImage(img, sx, sy, fw, fh, dx, dy, dw, dh);
  if (flashWhite) {
    const sil = getWhiteSilhouette(src, img);
    if (sil) {
      ctx.save();
      ctx.globalAlpha = 0.72;
      ctx.drawImage(sil, sx, sy, fw, fh, dx, dy, dw, dh);
      ctx.restore();
    }
  }
}

// ============================================================================
// Underlying Engine Optimization #3: Throttled WebAudio Bus (Zero Node Leak!)
// ============================================================================
let bgmAudio = null;
let sharedCryAudio = null;
let lastCryMs = 0;
let curBgmIdx = 0;

function playBgmTrack(idx, loop = true) {
  try {
    curBgmIdx = ((idx % BGM_TRACKS.length) + BGM_TRACKS.length) % BGM_TRACKS.length;
    const tr = BGM_TRACKS[curBgmIdx];
    if (!bgmAudio) {
      bgmAudio = new Audio();
      bgmAudio.volume = 0.42;
    } else {
      bgmAudio.pause();
    }
    bgmAudio.src = tr.file;
    bgmAudio.loop = true; // Keep looping current track so mid-combat never triggers synchronous MediaPlayer decode stalls!
    bgmAudio.play().catch(() => {});
    if (RUN) {
      addPopup(RUN.x, RUN.y - 52, `🎵 BGM：${tr.name}`, "#81d4fa", 1.08);
    }
  } catch (e) {}
}

function nextStageBgm() {
  if (RUN && RUN.stage && RUN.stage.bgmPool) {
    const pool = RUN.stage.bgmPool;
    const pick = pool[Math.floor(Math.random() * pool.length)];
    playBgmTrack(pick, true);
  } else {
    playBgmTrack((curBgmIdx + 1) % BGM_TRACKS.length, true);
  }
}

function playCry(pid) {
  try {
    const nowMs = performance.now();
    if (nowMs - lastCryMs < 350) return; // Throttle cries so simultaneous spawns/evolutions never lock Android MediaPlayer!
    lastCryMs = nowMs;
    if (!sharedCryAudio) {
      sharedCryAudio = new Audio();
      sharedCryAudio.volume = 0.42;
    } else {
      sharedCryAudio.pause();
    }
    sharedCryAudio.src = `./assets/cries/${pid}.ogg`;
    sharedCryAudio.play().catch(() => {});
  } catch (e) {}
}

let audioCtx = null;
let activeOscCount = 0;
let lastHitSfxTime = 0;
let lastGemSfxTime = 0;

function sfx(type) {
  try {
    const nowMs = performance.now();
    if (type === "hit") {
      if (nowMs - lastHitSfxTime < 85) return;
      lastHitSfxTime = nowMs;
    } else if (type === "gem") {
      if (nowMs - lastGemSfxTime < 70) return;
      lastGemSfxTime = nowMs;
    }
    if (activeOscCount >= 6 && (type === "hit" || type === "gem")) return;
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === "suspended") {
      audioCtx.resume().catch(() => {});
      return;
    }
    const now = audioCtx.currentTime;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    activeOscCount++;
    osc.onended = () => {
      activeOscCount = Math.max(0, activeOscCount - 1);
      try { osc.disconnect(); gain.disconnect(); } catch (e) {}
    };
    if (type === "gem") {
      osc.type = "sine";
      osc.frequency.setValueAtTime(720, now);
      osc.frequency.exponentialRampToValueAtTime(1150, now + 0.05);
      gain.gain.setValueAtTime(0.055, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.055);
      osc.start(now); osc.stop(now + 0.06);
    } else if (type === "hit") {
      osc.type = "triangle";
      osc.frequency.setValueAtTime(160, now);
      osc.frequency.linearRampToValueAtTime(65, now + 0.045);
      gain.gain.setValueAtTime(0.04, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.045);
      osc.start(now); osc.stop(now + 0.05);
    } else if (type === "level") {
      osc.type = "square";
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.setValueAtTime(554, now + 0.07);
      osc.frequency.setValueAtTime(659, now + 0.14);
      osc.frequency.setValueAtTime(880, now + 0.21);
      gain.gain.setValueAtTime(0.08, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.34);
      osc.start(now); osc.stop(now + 0.35);
    } else if (type === "chest") {
      osc.type = "triangle";
      osc.frequency.setValueAtTime(523, now);
      osc.frequency.setValueAtTime(659, now + 0.08);
      osc.frequency.setValueAtTime(784, now + 0.16);
      osc.frequency.setValueAtTime(1046, now + 0.24);
      gain.gain.setValueAtTime(0.10, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.45);
      osc.start(now); osc.stop(now + 0.46);
    }
  } catch (e) {}
}

function getStartingMoves(starterId) {
  const ls = STARTER_LEARNSETS[starterId]?.levelMoves || [];
  const lv1 = ls.filter(x => x[1] <= 1).map(x => x[0]);
  return lv1.slice(0, 2);
}

